(() => {
  'use strict';
  const data = window.ATLAS_DATA || {conferences: [], meta: {}};
  const conferences = data.conferences || [];
  const app = document.querySelector('#app');
  const symbols = {
    globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-4 5-4 13 0 18M12 3c4 5 4 13 0 18M12 3v18"/>',
    search:'<circle cx="10.8" cy="10.8" r="7"/><path d="m16 16 5 5"/>',
    bookmark:'<path d="M6 4a2 2 0 0 1 2-2h8a2 2 0 0 1 2 2v18l-6-4-6 4z"/>',
    calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',
    pin:'<path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',
    arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
    external:'<path d="M13 5h6v6M19 5l-9 9"/><path d="M19 13v5a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1h5"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',
    x:'<path d="M18 6 6 18M6 6l12 12"/>',
    chevronL:'<path d="m15 18-6-6 6-6"/>',
    chevronR:'<path d="m9 18 6-6-6-6"/>',
    list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',
    grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
    shield:'<path d="M12 22c-5-3-8-7-8-12V5l8-3 8 3v5c0 5-3 9-8 12Z"/><path d="m9 12 2 2 4-4"/>',
    filter:'<path d="M4 6h16M7 12h10m-7 6h4"/>',
    spark:'<path d="m12 2 2 7 7 3-7 3-2 7-3-7-7-3 7-3 3-7Z"/>',
    refresh:'<path d="M20 11a8 8 0 1 0-2 6m2-11v5h-5"/>',
    bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 8-3 10h18c0-2-3-3-3-10M10 21h4"/>',
    download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v3h16v-3"/>',
    layers:'<path d="m12 2 9 5-9 5-9-5 9-5Zm-9 10 9 5 9-5M3 17l9 5 9-5"/>',
    heart:'<path d="M20 7c-2-3-6-2-8 1-2-3-6-4-8-1-3 5 4 11 8 14 4-3 11-9 8-14Z"/>',
    check:'<path d="m4 12 5 5L20 6"/>',
    minus:'<path d="M5 12h14"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
    compass:'<circle cx="12" cy="12" r="9"/><path d="m15 9-2 4-4 2 2-4 4-2Z"/>'
  };
  const icon = (n,s=18) => `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${symbols[n] || symbols.globe}</svg>`;
  const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const safeURL = url => /^https:\/\//.test(String(url || '')) ? url : '#';
  const localToday = () => { const n=new Date(); return `${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}-${String(n.getDate()).padStart(2,'0')}`; };
  const dayDiff=(a,b)=>{if(!a||!b)return null;return Math.round((Date.parse(a+'T00:00:00Z')-Date.parse(b+'T00:00:00Z'))/86400000);};
  const dateParts=(s)=>s?new Date(`${s}T12:00:00Z`):null;
  const dateFmt=(s,year=true)=>s?dateParts(s).toLocaleDateString('en-GB',{day:'numeric',month:'short',...(year?{year:'numeric'}:{}),timeZone:'UTC'}):'Not announced';
  const longDate=s=>s?dateParts(s).toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}):'Not announced';
  const rangeFmt=c=>!c.startDate?'To be announced':`${dateFmt(c.startDate,c.startDate?.slice(0,4)!==c.endDate?.slice(0,4))} – ${dateFmt(c.endDate)}`;
  const duration=c=>c.startDate&&c.endDate?dayDiff(c.endDate,c.startDate)+1:null;
  let state = {route:'home',search:'',field:'All fields',years:[],regions:[],status:'All statuses',view:'table',sort:'deadline',savedOnly:false,month:new Date().getMonth(),calYear:new Date().getFullYear(),selectedDate:localToday(),calType:'all',drawer:null,mobileMenu:false,mapField:'All fields',mapYear:'All years',mapRegionFilter:'All regions',mapSearch:'',mapSavedOnly:false,mapSelected:'irspm-2027',mapZoom:1,mapCenter:{x:600,y:305},mapFocus:'World'};
  try{state.saved=new Set(JSON.parse(localStorage.getItem('atlas_saved_v1')||'[]'));}catch(e){state.saved=new Set();}
  const eventTypes={submission:'Submission',registration:'Registration',conference:'Conference',notification:'Notification'};
  function eventList(){let out=[];for(const c of conferences){for(const d of c.deadlines||[])if(d.date)out.push({id:c.id+'-'+d.type.toLowerCase().replace(/\s/g,'-'),date:d.date,type:'submission',label:`${d.type} submission deadline`,conference:c,source:d.source});if(c.registration?.earlyBird)out.push({id:c.id+'-early',date:c.registration.earlyBird,type:'registration',label:'Early-bird registration deadline',conference:c,source:c.registration.source});if(c.registration?.closes)out.push({id:c.id+'-reg',date:c.registration.closes,type:'registration',label:'Registration deadline',conference:c,source:c.registration.source});if(c.notificationDate)out.push({id:c.id+'-notification',date:c.notificationDate,type:'notification',label:'Acceptance notification',conference:c});if(c.startDate)out.push({id:c.id+'-conference',date:c.startDate,type:'conference',label:'Conference begins',conference:c});}return out.sort((a,b)=>a.date.localeCompare(b.date));}
  const events=eventList();
  const nextSubmission=c=>(c.deadlines||[]).filter(d=>d.date&&d.date>=localToday()&&d.phase!=='supplemental').sort((a,b)=>a.date.localeCompare(b.date))[0]||null;
  const firstSubmission=c=>(c.deadlines||[]).filter(d=>d.date&&d.phase!=='supplemental').sort((a,b)=>b.date.localeCompare(a.date))[0]||null;
  const nextRelevant=c=>{const n=nextSubmission(c);if(n)return {...n,kind:'submission'};if(c.registration?.closes&&c.registration.closes>=localToday())return {date:c.registration.closes,type:'Registration',kind:'registration'};return null;};
  function status(c){const t=localToday();if(c.endDate&&c.endDate<t)return {name:'Completed',tone:'gray',key:'past'};let d=nextSubmission(c);if(d){if(d.openDate&&d.openDate>t)return {name:'Opening soon',tone:'blue',key:'upcoming'};const left=dayDiff(d.date,t);return left<=14?{name:'Closing soon',tone:'red',key:'closing'}:{name:'Submission open',tone:'green',key:'open'};}if((c.deadlines||[]).length)return {name:'Submission closed',tone:'gray',key:'closed'};if(c.registration?.closes&&c.registration.closes>=t)return {name:'Registration open',tone:'green',key:'open'};return {name:'CFP not announced',tone:'blue',key:'upcoming'};}
  const statusBadge=c=>{const s=status(c);return `<span class="pill ${s.tone}">${esc(s.name)}</span>`;};
  function nav(){const route=state.route;return `<header class="site-header"><div class="header-inner"><a href="#/home" class="brand" aria-label="Conference Atlas home"><span class="brand-mark">${icon('globe',23)}</span><span class="brand-name">Conference Atlas</span></a><nav class="nav-links" aria-label="Primary navigation"><a href="#/home" class="${route==='home'?'active':''}">Home</a><a href="#/explore" class="${route==='explore'?'active':''}">Explore</a><a href="#/calendar" class="${route==='calendar'?'active':''}">Calendar</a><a href="#/map" class="${route==='map'?'active':''}">Map</a><a href="#/status" class="${route==='status'?'active':''}">Data Status</a></nav><div class="header-actions"><button class="icon-btn header-search" aria-label="Go to search" data-action="search">${icon('search',19)}</button><button class="icon-btn" aria-label="Saved conferences" data-action="saved">${icon('bookmark',18)}${state.saved.size?`<span class="saved-count">${state.saved.size}</span>`:''}</button></div></div></header>`;}
  function footer(){return `<footer class="footer"><div class="footer-inner"><div><span class="footer-brand">Conference Atlas</span><br/><small>Built for curious minds and meaningful research.</small></div><small>${conferences.length} curated editions · Official sources · Curated ${dateFmt(data.meta?.curatedAsOf||'2026-10-11')} · <a href="https://github.com" target="_blank" rel="noreferrer">Independent academic prototype</a></small></div></footer>`;}
  const daysBadge = days => days==null?'': days===0?`<span class="pill red">Today</span>`:days>0?`<span class="pill ${days<=14?'red':days<=30?'amber':'green'}">${days} days left</span>`:`<span class="pill gray">Closed</span>`;
  function conferenceCard(c){const d=nextRelevant(c)||firstSubmission(c);const delta=d?dayDiff(d.date,localToday()):null;let dateLabel=d?`${d.type||'Submission'} ${d.kind==='registration'?'deadline':'deadline'}`:'Conference dates';let dateValue=d?dateFmt(d.date):rangeFmt(c);return `<article class="conf-card"><div class="card-cover ${esc(c.art||'boston')}"><div class="cover-circle"></div><div class="cover-ring"></div><div class="cover-horizon"></div><div class="cover-tag">${esc(c.city)}, ${esc(c.country)}</div><div class="cover-year">${esc(c.year)}</div></div><div class="card-body"><div class="card-row"><strong class="card-title">${esc(c.acronym)}</strong>${statusBadge(c)}</div><div class="card-fullname">${esc(c.name)}</div><div class="mini-info">${icon('calendar',14)}${esc(rangeFmt(c))}</div><div class="mini-info">${icon('pin',14)}${esc(c.city+', '+c.country)}</div><div class="card-divider"></div><div class="deadline-card"><div><div class="tiny-label">${esc(dateLabel)}</div><div class="deadline-value">${esc(dateValue)}</div><div style="margin-top:6px">${d?daysBadge(delta):'<span class="pill blue">Date confirmed</span>'}</div></div><div class="card-actions"><button class="save-btn ${state.saved.has(c.id)?'saved':''}" data-action="toggle-save" data-id="${esc(c.id)}" aria-label="${state.saved.has(c.id)?'Remove from':'Add to'} saved">${icon('bookmark',16)}</button><button class="round-go" aria-label="View ${esc(c.acronym)} details" data-action="detail" data-id="${esc(c.id)}">${icon('arrow',17)}</button></div></div></div></article>`;}
  function stat(iconName,value,label){return `<div class="stat"><span class="stat-icon">${icon(iconName,21)}</span><div><div class="stat-value">${esc(value)}</div><div class="stat-label">${esc(label)}</div></div></div>`;}
  function home(){const now=localToday(), future=events.filter(e=>e.date>=now&&e.type!=='conference').slice(0,4);const numCountries=new Set(conferences.map(c=>c.country)).size,numFields=new Set(conferences.flatMap(c=>c.fields)).size;const picks=['irspm-2027','icpp8-2027','iaia-2027','appam-2026','pmrc-2027','aspa-2027'].map(id=>conferences.find(c=>c.id===id)).filter(Boolean);
    const fields=['Public Policy','Public Administration','Public Management','Governance','Environmental Policy','Policy Analysis'];
    return `<main class="page"><div class="container hero-shell"><section class="hero"><img src="assets/hero-academia.svg" class="hero-illustration" alt="Decorative illustration of a historic university skyline"/><div class="hero-content"><div class="eyebrow"><span></span>YOUR RESEARCH, WITHOUT BORDERS</div><h1>Discover the world's academic conferences.</h1><p>One place to explore, compare and keep track of international conferences in public policy, public administration and public management.</p><form class="search-large" id="heroSearch">${icon('search',18)}<input id="homeSearch" type="search" aria-label="Search conferences" placeholder="Search conferences, topics, or locations…" value="${esc(state.search)}"/><button aria-label="Search conferences" type="submit">${icon('arrow',21)}</button></form><div class="popular-chips"><span>EXPLORE</span>${['Public Policy','Public Administration','Governance','Environmental Policy'].map(f=>`<button data-action="field" data-field="${esc(f)}">${esc(f)}</button>`).join('')}</div></div></section><div class="stats">${stat('globe',conferences.length+'','Verified editions')}${stat('pin',numCountries+'','Countries represented')}${stat('layers',numFields+'','Research fields')}${stat('shield','Official','Source-first tracking')}</div>
    <section class="section"><div class="section-header"><div><h2 class="section-title">Featured conferences</h2><p class="section-subtitle">Explore major conferences across public policy and administration.</p></div><button class="text-link" data-action="explore">View all conferences ${icon('arrow',15)}</button></div><div class="featured-grid">${picks.slice(0,6).map(conferenceCard).join('')}</div></section>
    <section class="section"><div class="section-header"><div><h2 class="section-title">Explore by research field</h2><p class="section-subtitle">Find the conversations that matter to your work.</p></div></div><div class="field-grid">${fields.map((f,i)=>`<button class="field-tile" data-action="field" data-field="${esc(f)}"><span class="field-symbol">${icon(['layers','globe','shield','spark','heart','filter'][i],18)}</span><span><strong>${esc(f)}</strong><small>${conferences.filter(c=>c.fields.includes(f)).length} editions</small></span></button>`).join('')}</div></section>
    <div class="home-lower"><section class="slim-panel"><h2 class="slim-title">Deadlines on the horizon</h2><p class="slim-desc">Upcoming milestones, ordered by date.</p>${future.length?future.map(e=>`<div class="upcoming-row"><span class="due-day"><strong>${esc(dateParts(e.date).getUTCDate())}</strong><span>${esc(dateParts(e.date).toLocaleDateString('en',{month:'short',timeZone:'UTC'}))}</span></span><div><div class="upcoming-title">${esc(e.conference.acronym)}</div><div class="upcoming-meta">${esc(e.label)}</div></div><span class="date-chip">${dayDiff(e.date,now)}d left</span></div>`).join(''):'<p class="events-muted">No future deadlines announced yet.</p>'}<button class="text-link" data-action="calendar" style="margin-top:12px">Open deadline calendar ${icon('arrow',15)}</button></section><section class="slim-panel home-message"><div class="eyebrow" style="color:#b0cde0">PLAN WITH CONFIDENCE</div><h2 class="slim-title">More time for research.<br/>Less time searching.</h2><p>Separate submission types, track key dates and follow the original announcement. Your next conference begins with a better plan.</p><button class="btn-light" data-action="explore">Browse conference database ${icon('arrow',16)}</button><button class="btn-hero-map" data-action="map">${icon('pin',15)} Explore world map ${icon('arrow',15)}</button></section></div></div></main>`;
  }
  function availableFields(){return [...new Set(conferences.flatMap(c=>c.fields))].sort();}
  function filtered(){let r=conferences.filter(c=>{
    const t=state.search.trim().toLowerCase();const combined=[c.acronym,c.name,c.city,c.country,c.organizer,c.theme,c.description,...c.fields,...c.topics].join(' ').toLowerCase();
    return (!t||combined.includes(t))&&(state.field==='All fields'||c.fields.includes(state.field))&&(!state.years.length||state.years.includes(String(c.year)))&&(!state.regions.length||state.regions.includes(c.region))&&(state.status==='All statuses'||state.status===status(c).key)&&(!state.savedOnly||state.saved.has(c.id));
  });let metric=c=>nextRelevant(c)?.date||c.startDate||'9999-12-31';r.sort((a,b)=>state.sort==='name'?a.acronym.localeCompare(b.acronym):state.sort==='conference'?((a.startDate||'9999').localeCompare(b.startDate||'9999')):state.sort==='latest'?((b.startDate||'').localeCompare(a.startDate||'')):metric(a).localeCompare(metric(b)));return r;}
  function filters(){const availableYears=[...new Set(conferences.map(c=>String(c.year)))].sort();const regions=[...new Set(conferences.map(c=>c.region))].sort();const check=(kind,key,label,count,active)=>`<label class="check-line"><input type="checkbox" data-check="${kind}" value="${esc(key)}" ${active?'checked':''}/>${esc(label)}<span class="filter-count">${count}</span></label>`;
    return `<aside class="filter-panel"><div class="filter-heading"><strong>Filters</strong><button class="clear-btn" data-action="clear">Clear all</button></div><section class="filter-group"><div>RESEARCH FIELD</div>${check('field','All fields','All research fields',conferences.length,state.field==='All fields')}${availableFields().map(f=>check('field',f,f,conferences.filter(c=>c.fields.includes(f)).length,state.field===f)).join('')}</section><section class="filter-group"><div>YEAR</div>${availableYears.map(y=>check('year',y,y,conferences.filter(c=>String(c.year)===y).length,state.years.includes(y))).join('')}</section><section class="filter-group"><div>REGION</div>${regions.map(r=>check('region',r,r,conferences.filter(c=>c.region===r).length,state.regions.includes(r))).join('')}</section><section class="filter-group"><div>SUBMISSION STATUS</div>${[['All statuses','All statuses'],['open','Submission / registration open'],['closing','Closing soon'],['upcoming','Upcoming / not announced'],['closed','Submissions closed']].map(([key,label])=>check('status',key,label,'',state.status===key)).join('')}</section><section class="filter-group"><div>PERSONAL COLLECTION</div>${check('saved','yes','Saved only',state.saved.size,state.savedOnly)}</section></aside>`;}
  function tableRow(c){const d=nextRelevant(c)||firstSubmission(c);const left=d?dayDiff(d.date,localToday()):null;return `<tr><td><div class="name-layout"><span class="table-badge">${icon('globe',17)}</span><div><button class="table-name" data-action="detail" data-id="${esc(c.id)}">${esc(c.acronym)}</button><div class="table-org">${esc(c.name)}</div></div></div></td><td><strong style="color:#284f70">${esc(rangeFmt(c))}</strong><br/><small class="table-small">${duration(c)||'—'} days</small></td><td>${esc(c.city)}<br/><small class="table-small">${esc(c.country)}</small></td><td>${d?`<strong style="color:#214b70">${esc(dateFmt(d.date))}</strong><br/><small class="table-small">${esc(d.type)}</small>`:'<span class="muted-value">Not announced</span>'}</td><td>${left!=null?`<span class="table-day ${left>=0&&left<=14?'urgent':''}">${left>=0?left+' days':'Passed'}</span>`:'<span class="muted-value">—</span>'}</td><td>${statusBadge(c)}</td><td><button class="favourite-control" aria-label="${state.saved.has(c.id)?'Unsave':'Save'} ${esc(c.acronym)}" data-action="toggle-save" data-id="${esc(c.id)}" style="color:${state.saved.has(c.id)?'#1d689d':'#879aaa'}">${icon('bookmark',17)}</button></td></tr>`;}
  function explore(){const rows=filtered();return `<main class="page container"><div class="page-head"><div class="page-kicker">DISCOVER / TRACK / SUBMIT</div><h1 class="page-title">Conference Directory</h1><p class="page-desc">Explore official conference announcements, compare deadlines and find your next academic community.</p></div><div class="explore-layout">${filters()}<section class="list-main"><div class="list-toolbar"><div class="list-total">Conferences (${rows.length})<small>${state.savedOnly?'saved only':'curated editions'}</small></div><div class="toolbar-controls"><div class="mini-search">${icon('search',15)}<input id="listSearch" placeholder="Search conferences…" aria-label="Search conference directory" value="${esc(state.search)}"/></div><select id="sort" class="sort-select" aria-label="Sort conferences"><option value="deadline" ${state.sort==='deadline'?'selected':''}>Next relevant deadline</option><option value="conference" ${state.sort==='conference'?'selected':''}>Conference date ↑</option><option value="latest" ${state.sort==='latest'?'selected':''}>Conference date ↓</option><option value="name" ${state.sort==='name'?'selected':''}>Conference name</option></select><div class="view-toggle"><button data-action="view-table" class="${state.view==='table'?'active':''}">${icon('list',13)} Table</button><button data-action="view-cards" class="${state.view==='cards'?'active':''}">${icon('grid',13)} Cards</button><button data-action="map" aria-label="Map view">${icon('pin',13)} Map</button></div></div></div>${rows.length?(state.view==='table'?`<div class="table-wrap"><table class="conf-table"><thead><tr><th>Conference</th><th>When</th><th>Where</th><th>Next / last deadline</th><th>Time left</th><th>Status</th><th>Save</th></tr></thead><tbody>${rows.map(tableRow).join('')}</tbody></table></div>`:`<div class="result-cards">${rows.map(conferenceCard).join('')}</div>`):`<div class="empty-state">${icon('search',32)}<h3>No matching conferences</h3><p>Try a broader research field or clear some filters.</p><button class="btn-secondary" style="margin:auto" data-action="clear">Clear filters</button></div>`}<p class="tiny-footer">All dates are from linked official pages. “Not announced” means the corresponding information is not verified or has not been published. Dates can change — always check the source before submitting.</p></section></div></main>`;}
  function calendarEventsForDate(date,type='all'){return events.filter(e=>e.date===date&&(type==='all'||type===e.type));}
  function calendarDays(){const first=new Date(Date.UTC(state.calYear,state.month,1));const firstMon=(first.getUTCDay()+6)%7;let cells=[];for(let i=0;i<42;i++){let d=new Date(Date.UTC(state.calYear,state.month,1-firstMon+i));let ds=d.toISOString().slice(0,10);const evs=calendarEventsForDate(ds);let outside=d.getUTCMonth()!==state.month;cells.push(`<button class="calendar-day ${outside?'outside':''} ${ds===state.selectedDate?'selected':''} ${ds===localToday()?'today':''}" data-action="select-day" data-date="${ds}" aria-label="${esc(longDate(ds))}, ${evs.length} events" title="${esc(longDate(ds))}: ${evs.length} events"><span class="date-number">${d.getUTCDate()}</span><span class="dots">${evs.slice(0,5).map(e=>`<i class="dot ${e.type}"></i>`).join('')}</span></button>`);}return cells.join('');}
  function agendaItem(e){const left=dayDiff(e.date,localToday());return `<button class="agenda-item" data-action="detail" data-id="${esc(e.conference.id)}"><i class="dot ${e.type}"></i><span style="flex:1"><strong>${esc(e.conference.acronym)}</strong><small>${esc(e.label)}</small></span><span class="agenda-days">${left>0?left+'d left':left===0?'Today':''}</span></button>`;}
  function calendar(){const monthName=new Date(Date.UTC(state.calYear,state.month,1)).toLocaleDateString('en-GB',{month:'long',year:'numeric',timeZone:'UTC'});const selected=calendarEventsForDate(state.selectedDate,state.calType);const upcoming=events.filter(e=>e.date>=localToday()&&(state.calType==='all'||state.calType===e.type)).slice(0,9);const display=(selected.length?selected:upcoming),grouped=new Map();for(const e of display){if(!grouped.has(e.date))grouped.set(e.date,[]);grouped.get(e.date).push(e);}return `<main class="page container"><div class="page-head"><div class="page-kicker">EVERY DATE, IN ONE PLACE</div><h1 class="page-title">Academic Calendar</h1><p class="page-desc">See submission deadlines, registration windows and conference dates side by side.</p></div><div class="calendar-layout"><section class="calendar-board"><div class="calendar-head"><div class="calendar-month">${esc(monthName)}</div><div class="month-controls"><button class="control-btn" data-action="prev-month" aria-label="Previous month">${icon('chevronL',16)}</button><button class="control-btn" data-action="today">Today</button><button class="control-btn" data-action="next-month" aria-label="Next month">${icon('chevronR',16)}</button></div></div><div class="weekdays">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-cells">${calendarDays()}</div><div class="calendar-legend">${Object.entries(eventTypes).map(([id,label])=>`<span><i class="dot ${id}"></i>${label}</span>`).join('')}</div><div class="calendar-note">${icon('shield',15)} Dates reflect published official announcements. If the organizer changes a deadline, the next configured source check can flag or update it. Time-zone-specific cut-off times should always be checked on the organizer’s website.</div></section><aside class="agenda-panel"><div class="agenda-header"><h2 class="agenda-title">Upcoming milestones</h2><span class="pill blue">${events.filter(e=>e.date>=localToday()).length} ahead</span></div><div class="segmented">${[['all','All events'],['submission','Submissions'],['registration','Registration'],['conference','Conferences']].map(([key,value])=>`<button data-action="cal-filter" data-type="${key}" class="${state.calType===key?'active':''}">${value}</button>`).join('')}</div><div class="agenda-selected"><h3>${esc(longDate(state.selectedDate))}</h3><p>${selected.length?`${selected.length} matching event${selected.length>1?'s':''} on this day`:'No matching event on this date. Showing upcoming events below.'}</p></div>${grouped.size?[...grouped.entries()].map(([day,es])=>`<div class="agenda-date">${esc(longDate(day))}<span style="float:right;color:#a1adb7;font-size:10px">${es.length} event${es.length===1?'':'s'}</span></div>${es.map(agendaItem).join('')}`).join(''):'<div class="events-muted">No upcoming milestones are currently recorded for this category.</div>'}<button class="btn-secondary" data-action="download-ics" style="margin-top:22px;width:100%">${icon('download',15)} Export all milestones (.ics)</button></aside></div></main>`;}
  // Self-contained map: locally bundled Natural Earth geometry, city-level pins; no remote tile services.
  const ROB_X=[1,.9986,.9954,.99,.9822,.973,.96,.9427,.9216,.8962,.8679,.835,.7986,.7597,.7186,.6732,.6213,.5722,.5322];
  const ROB_Y=[0,.062,.124,.186,.248,.31,.372,.434,.4958,.5571,.6176,.6769,.7346,.7903,.8435,.8936,.9394,.9761,1];
  function mapProject(c){if(!c?.geo||!Number.isFinite(c.geo.lat)||!Number.isFinite(c.geo.lon))return null;const lat=Math.min(90,Math.max(-90,c.geo.lat)),lon=Math.min(180,Math.max(-180,c.geo.lon)),j=Math.min(17,Math.floor(Math.min(Math.abs(lat),89.999)/5)),t=(Math.abs(lat)-j*5)/5,x=ROB_X[j]*(1-t)+ROB_X[j+1]*t,y=ROB_Y[j]*(1-t)+ROB_Y[j+1]*t;return {x:600+205*.8487*(lon*Math.PI/180)*x,y:305-205*1.3523*Math.sign(lat)*y};}
  function mapResults(){const search=state.mapSearch.trim().toLowerCase();return conferences.filter(c=>c.geo&&(!search||[c.acronym,c.name,c.city,c.country,c.region,c.theme,c.organizer,...(c.fields||[]),...(c.topics||[])].join(' ').toLowerCase().includes(search))&&(state.mapField==='All fields'||c.fields.includes(state.mapField))&&(state.mapYear==='All years'||String(c.year)===state.mapYear)&&(state.mapRegionFilter==='All regions'||c.region===state.mapRegionFilter)&&(!state.mapSavedOnly||state.saved.has(c.id))).sort((a,b)=>(a.startDate||'').localeCompare(b.startDate||''));}
  function mapViewBox(){const zoom=state.mapZoom,width=1200/zoom,height=610/zoom,x=Math.max(0,Math.min(1200-width,state.mapCenter.x-width/2)),y=Math.max(0,Math.min(610-height,state.mapCenter.y-height/2));return {x,y,width,height};}
  function mapMarker(c){const p=mapProject(c),active=state.mapSelected===c.id,tone=status(c).tone;return `<g class="atlas-marker ${active?'selected':''} marker-${tone}" role="button" tabindex="0" data-action="map-select" data-id="${esc(c.id)}" aria-label="View ${esc(c.acronym)} in ${esc(c.city)}" transform="translate(${p.x.toFixed(2)} ${p.y.toFixed(2)})"><title>${esc(c.acronym+' · '+c.city+', '+c.country)}</title><circle class="marker-halo" r="${active?24:16}"/><circle class="marker-hit" r="19"/><circle class="marker-ring" r="${active?10:8}"/><circle class="marker-core" r="${active?4.4:3.4}"/>${active?`<g class="marker-label"><rect x="15" y="-34" rx="8" width="${Math.max(80,c.acronym.length*7.6+20)}" height="25"/><text x="26" y="-17">${esc(c.acronym)}</text></g>`:''}</g>`;}
  function mapVenue(c){return c?`${esc(c.city)}, ${esc(c.country)}`:'';}
  function mapFeatured(c){if(!c)return `<div class="map-mapcallout"><span class="map-callout-icon">${icon('pin',20)}</span><div><strong>Select a city on the map</strong><small>Explore verified conference locations.</small></div></div>`;
    const d=nextRelevant(c),date=d?dateFmt(d.date):'Not announced',left=d?dayDiff(d.date,localToday()):null;
    return `<div class="map-feature-card"><div class="map-feature-top"><span class="map-feature-eyebrow">SELECTED CONFERENCE</span>${statusBadge(c)}</div><strong>${esc(c.acronym)}</strong><div class="map-feature-name">${esc(c.name)}</div><div class="map-feature-meta">${icon('pin',14)} ${mapVenue(c)} <span>·</span> ${icon('calendar',14)} ${esc(rangeFmt(c))}</div><div class="map-feature-bottom"><span><span class="tiny-label">Next deadline</span><b>${esc(date)}${left!=null&&left>=0?` · ${left}d left`:''}</b></span><button class="map-details-btn" data-action="detail" data-id="${esc(c.id)}">View details ${icon('arrow',15)}</button></div></div>`;
  }
  function map(){const matches=mapResults();let selected=matches.find(c=>c.id===state.mapSelected);if(!selected&&matches.length){selected=matches[0];state.mapSelected=selected.id;}if(!matches.length)selected=null;
    const countries=new Set(matches.map(c=>c.country)).size,cities=new Set(matches.map(c=>`${c.city}|${c.country}`)).size;
    const box=mapViewBox(),viewBox=[box.x,box.y,box.width,box.height].join(' ');
    const years=[...new Set(conferences.map(c=>String(c.year)))].sort(),regions=[...new Set(conferences.map(c=>c.region))].sort();
    const select=(name,value,items)=>`<label class="map-select-wrap"><span>${name}</span><select data-map-filter="${value}" aria-label="Filter map by ${name.toLowerCase()}">${items.map(x=>`<option value="${esc(x)}" ${state[value]===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;
    return `<main class="page container map-page"><div class="map-page-heading"><div><div class="page-kicker">THE WORLD OF PUBLIC POLICY RESEARCH</div><h1 class="page-title">Conferences around the world<span class="map-title-period">.</span></h1><p class="page-desc">Discover where ideas meet. Explore conference destinations, submission windows and research communities on one interactive map.</p></div><div class="map-metrics"><div><b>${matches.length}</b><small>Conference editions</small></div><div><b>${cities}</b><small>Host cities</small></div><div><b>${countries}</b><small>Countries</small></div></div></div>
    <div class="map-filterbar"><label class="map-search">${icon('search',18)}<input id="mapSearch" aria-label="Search conference locations" placeholder="Search conference, city, or topic…" value="${esc(state.mapSearch)}"/></label>${select('Research field','mapField',['All fields',...availableFields()])}${select('Year','mapYear',['All years',...years])}${select('Region','mapRegionFilter',['All regions',...regions])}<label class="map-saved-wrap"><input type="checkbox" id="mapSavedOnly" ${state.mapSavedOnly?'checked':''}/> Saved only</label><button class="map-reset-filters" data-action="map-clear">Reset filters</button></div>
    <div class="map-layout"><section class="map-board" aria-label="Conference location map"><div class="map-board-top"><div class="map-board-label"><span class="live-circle"></span> GLOBAL CONFERENCE MAP <span class="map-board-sep">/</span> <small>${matches.length} locations</small></div><div class="map-zoom"><button data-action="map-zoom-in" title="Zoom in" aria-label="Zoom in">${icon('plus',17)}</button><button data-action="map-zoom-out" title="Zoom out" aria-label="Zoom out">${icon('minus',17)}</button><button data-action="map-world" title="Reset map" aria-label="Reset map">${icon('compass',17)}</button></div></div>
    <div class="atlas-map-viewport" aria-label="Map showing ${matches.length} host cities; select a pin to see details"><svg id="atlasMapSVG" class="atlas-svg" viewBox="${viewBox}" preserveAspectRatio="xMidYMid meet" role="group" aria-label="Interactive world map"><image href="assets/world-map.svg" x="0" y="0" width="1200" height="610"/>${matches.map(mapMarker).join('')}</svg><span class="map-corner-note">City-level locations · ${Math.round(state.mapZoom*100)}% zoom</span>${mapFeatured(selected)}</div>
    <div class="map-board-foot"><div class="map-region-controls">${['World','Europe','North America','Asia–Pacific'].map(v=>`<button data-action="map-focus" data-focus="${v}" class="${state.mapFocus===v?'active':''}">${v}</button>`).join('')}</div><div class="map-legend"><span><i class="legend-dot closing"></i>Closing soon</span><span><i class="legend-dot open"></i>Open</span><span><i class="legend-dot other"></i>Other</span></div></div></section>
    <aside class="map-list-panel"><div class="map-list-header"><div><span class="page-kicker">YOUR NEXT DESTINATION</span><h2>Conference locations</h2><p>Choose a conference to highlight it on the map.</p></div><span class="map-results-count">${matches.length}</span></div><div class="map-location-list">${matches.length?matches.map(c=>{const d=nextRelevant(c)||firstSubmission(c),left=d?dayDiff(d.date,localToday()):null;return `<button class="map-location-item ${state.mapSelected===c.id?'active':''}" data-action="map-select" data-id="${esc(c.id)}"><span class="map-list-pin">${icon('pin',16)}</span><span class="map-list-copy"><strong>${esc(c.acronym)}</strong><small>${esc(c.city+', '+c.country)}</small><span class="map-list-date">${icon('calendar',12)} ${esc(rangeFmt(c))}</span></span><span class="map-list-end">${statusBadge(c)}${d?`<small>${esc(d.type)}: ${esc(dateFmt(d.date))}</small>`:'<small>Deadline not announced</small>'}${left!=null&&left>=0&&left<=30?`<em>${left}d left</em>`:''}</span></button>`}).join(''):`<div class="map-empty">${icon('pin',27)}<strong>No matching locations</strong><p>Try a different field or region.</p><button data-action="map-clear">Clear filters</button></div>`}</div><div class="map-list-footer">${icon('shield',16)} Locations are approximate city centres. Conference details and dates are based on the linked official sources.</div></aside></div><div class="map-source-note">${icon('globe',16)} Base geography: Natural Earth (public domain), locally bundled. No external map service or API key required. Only verified conference editions in our current database are shown.</div></main>`;
  }
  function mapZoom(multiplier){state.mapZoom=Math.max(1,Math.min(4,state.mapZoom*multiplier));state.mapFocus='';render();}
  function mapFocus(name){const centers={'World':{x:600,y:305,z:1},'Europe':{x:626,y:167,z:2.55},'North America':{x:375,y:193,z:2.25},'Asia–Pacific':{x:951,y:361,z:1.85}};const p=centers[name]||centers.World;const regions={'Europe':['Europe'],'North America':['North America'],'Asia–Pacific':['Asia','Oceania']};const matching=mapResults().find(c=>(regions[name]||[]).includes(c.region));if(matching)state.mapSelected=matching.id;state.mapCenter={x:p.x,y:p.y};state.mapZoom=p.z;state.mapFocus=name;render();}
  function mapSelect(id){const c=conferences.find(c=>c.id===id);if(!c)return;state.mapSelected=id;const p=mapProject(c);if(state.mapZoom>1.05){state.mapCenter=p;state.mapFocus='';}render();}
  const detailRow=(title,value)=>`<div class="detail-row"><span>${esc(title)}</span><strong>${value}</strong></div>`;
  const registrationValue=(c,s)=>{ if(!s) return esc('Not announced'); const days=dayDiff(c.startDate,s);return `${esc(dateFmt(s))}${days!=null?`<br/><small style="color:#8094a6;font-weight:500">${days} days before conference</small>`:''}`; };
  function detailDrawer(c){const s=status(c);const deadlineRows=(c.deadlines||[]).map(d=>{const days=dayDiff(c.startDate,d.date);return `<div class="detail-row"><span>${esc(d.type)} submission</span><strong>${esc(longDate(d.date))}<br/><small style="color:#8094a6;font-weight:500">${days!=null?`${days} days before conference`:''} ${d.openDate?' · Opens '+dateFmt(d.openDate):''}</small><br/><a href="${esc(safeURL(d.source||c.source))}" target="_blank" rel="noopener noreferrer">Official source ${icon('external',11)}</a></strong></div>`;}).join('');const cdesc=c.description||'';return `<div class="overlay" data-action="close-overlay"><aside class="drawer" role="dialog" aria-modal="true" aria-label="${esc(c.acronym)} details"><button class="icon-btn drawer-close" data-action="close" aria-label="Close conference details">${icon('x',21)}</button><div class="drawer-header"><div class="eyebrow"><span></span>CONFERENCE PROFILE</div><h2 class="drawer-title">${esc(c.acronym)}</h2><p class="drawer-name">${esc(c.name)}</p>${statusBadge(c)}</div><div class="drawer-banner"><div><strong>${esc(c.city)}, ${esc(c.country)}</strong><small>${esc(c.venue||'Venue not announced')}</small></div>${icon('globe',31)}</div><div class="drawer-section"><h3>Conference details</h3>${detailRow('Meeting dates',esc(rangeFmt(c)))}${detailRow('Duration',duration(c)?duration(c)+' days':'Not announced')}${detailRow('Format',esc(c.format||'Not announced'))}${detailRow('Organizer',esc(c.organizer))}${detailRow('Conference theme',esc(c.theme||'Not announced'))}</div><div class="drawer-section"><h3>Submission deadlines & lead times</h3>${deadlineRows||'<p>No verified call for submissions is currently available.</p>'}</div><div class="drawer-section"><h3>Registration milestones</h3>${detailRow('Registration opens',esc(dateFmt(c.registration?.opens)))}${detailRow('Early-bird deadline',registrationValue(c,c.registration?.earlyBird))}${detailRow('Registration deadline',registrationValue(c,c.registration?.closes))}${c.registration?.note?`<p style="margin-top:9px">${esc(c.registration.note)}</p>`:''}</div><div class="drawer-section"><h3>Research themes</h3><div class="detail-pill-list">${c.topics.map(topic=>`<span>${esc(topic)}</span>`).join('')}</div><p style="margin-top:14px">${esc(cdesc)}</p></div><div class="drawer-section"><h3>Data provenance</h3>${detailRow('Verification',esc(c.sourceStatus||'Unconfirmed'))}${detailRow('Last curated review',esc(dateFmt(c.verifiedAt)))}${c.editorialNote?`<p class="editorial-note"><strong>Important clarification</strong><br/>${esc(c.editorialNote)}</p>`:''}${detailRow('Primary source',`<a href="${esc(safeURL(c.source))}" rel="noopener noreferrer" target="_blank">Official announcement ${icon('external',12)}</a>`)}<p style="margin-top:12px">Unknown values are shown as “Not announced.” Always review the organizer's page for final deadlines and time-zone details.</p></div><div class="drawer-actions"><a class="btn-primary" href="${esc(safeURL(c.website))}" target="_blank" rel="noopener noreferrer">Official conference site ${icon('external',15)}</a><button class="btn-secondary" data-action="toggle-save" data-id="${esc(c.id)}">${icon('bookmark',15)} ${state.saved.has(c.id)?'Remove saved':'Save conference'}</button><button class="btn-secondary" data-action="download-single" data-id="${esc(c.id)}">${icon('download',15)} .ics</button></div></aside></div>`;}
  // Public, read-only operational transparency. A successful page fetch does not
  // certify every deadline on that page; historical values remain sourced.
  function dataStatus(){
    const report=data.status||{},sources=report.sources||[],leads=report.candidateLinks||[],pending=report.pendingDates||[],announcements=report.pendingAnnouncements||[];
    const successes=sources.filter(s=>s.state==='ok').length;
    const safeLink=(url,label='Official page')=>`<a class="status-external" href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${esc(label)} ${icon('external',13)}</a>`;
    const checkTime=s=>{if(!s)return 'Not checked yet';const dt=new Date(s);return Number.isNaN(dt.valueOf())?'Not available':dt.toLocaleString('en-GB',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+' UTC';};
    const latest=report.lastMonitoringCheck;
    const stale=!latest||((Date.now()-Date.parse(latest))>72*3600*1000);
    const checked=s=>s.state==='ok';
    return `<main class="page container data-status-page">
      <div class="page-head"><div class="page-kicker">TRANSPARENT DATA COLLECTION</div><div class="status-title-row"><div><h1 class="page-title">Data Status</h1><p class="page-desc">How current is the Conference Atlas catalogue? Explore our source checks, monitoring gaps and unverified leads.</p></div><span class="status-snapshot ${stale?'status-stale':''}">${icon('clock',15)} ${latest?'Last monitored '+esc(checkTime(latest)):'Monitoring has not run yet'}</span></div></div>
      <div class="status-metrics"><div class="status-metric"><span class="status-metric-label">Curated editions</span><strong>${conferences.length}</strong><small>Reviewed conference records</small></div><div class="status-metric"><span class="status-metric-label">Official source checks</span><strong>${successes}<em> / ${sources.length}</em></strong><small>Successful page monitors</small></div><div class="status-metric"><span class="status-metric-label">Date change reviews</span><strong>${pending.length+announcements.length}</strong><small>Not published automatically</small></div><div class="status-metric"><span class="status-metric-label">Unverified links</span><strong>${leads.length}</strong><small>Links, not new conferences</small></div></div>
      <div class="status-explainer">${icon('shield',20)}<span><strong>Official sources, cautious updates.</strong> Dates in the conference directory come from curated records. Monitoring checks whether source pages can be read, not whether every field has been independently reverified today. Potential links and ambiguous changes require manual review before publication.</span></div>
      <section class="status-section"><div class="status-section-heading"><div><div class="page-kicker">SOURCE HEALTH</div><h2>Official Website Monitoring</h2><p>Availability of the configured organizer pages at the last check. Unavailable sources retain previously confirmed information.</p></div><span class="status-mini-count">${successes} / ${sources.length} reachable</span></div><div class="status-table-scroll"><table class="status-table"><thead><tr><th>Organizer</th><th>Status</th><th>Last attempt (UTC)</th><th>Source</th></tr></thead><tbody>${sources.map(entry=>`<tr><td><strong>${esc(entry.organization)}</strong>${!checked(entry)&&entry.note?`<small class="status-note">${esc(entry.note)}</small>`:''}</td><td><span class="status-indicator ${checked(entry)?'ok':'warn'}"><i></i>${checked(entry)?'Checked':'Not checked'}</span></td><td>${esc(checkTime(entry.lastCheckedAt))}</td><td>${safeLink(entry.url,'Visit source')}</td></tr>`).join('')||'<tr><td colspan="4">Source monitoring has not been configured.</td></tr>'}</tbody></table></div></section>
      <section class="status-section"><div class="status-section-heading"><div><div class="page-kicker">REVIEW QUEUE</div><h2>Changes Awaiting Review</h2><p>Significant deadline differences or changes to announcement text must be checked against the official source.</p></div><span class="status-mini-count">${pending.length+announcements.length} items</span></div>${pending.length+announcements.length?`<div class="status-review-list">${pending.map(item=>`<div class="status-review-row"><span class="status-queue-mark">${icon('clock',17)}</span><div><strong>${esc(item.conferenceId)} · ${esc(item.field)}</strong><small>${esc(item.previous||'Not recorded')} → ${esc(item.observed||'Not recorded')} · ${esc(item.checkedAt||'')}</small></div>${safeLink(item.url,'Check date')}</div>`).join('')}${announcements.map(item=>`<div class="status-review-row"><span class="status-queue-mark">${icon('refresh',17)}</span><div><strong>${esc(item.organizer||'Organizer announcement')}</strong><small>${item.passageCount||0} changed excerpts · ${esc(checkTime(item.observedAt))}</small></div>${safeLink(item.url,'Check update')}</div>`).join('')}</div>`:`<div class="status-empty">${icon('check',20)} No queued deadline or announcement changes from the latest captured monitoring state.</div>`}</section>
      <section class="status-section"><div class="status-section-heading"><div><div class="page-kicker">DISCOVERY INBOX</div><h2>Potential Conference Links</h2><p>Automated discovery also finds guidelines, calendar downloads and other related material. None of these links is added to the directory without verification.</p></div><span class="status-mini-count">${leads.length} unverified links</span></div><div class="status-candidate-grid">${leads.slice(0,24).map(l=>`<article class="status-candidate"><div class="status-candidate-top"><span>${esc(l.year||'Year unknown')}</span><span class="status-indicator ${l.reviewType==='Potential conference link'?'review':'muted'}">${esc(l.reviewType||'Needs screening')}</span></div><strong>${esc(l.title)}</strong><div class="status-candidate-bottom">${safeLink(l.url,'Review source')}</div></article>`).join('')||'<div class="status-empty">No candidate links are currently recorded.</div>'}</div>${leads.length>24?`<p class="status-overflow">Displaying 24 of ${leads.length} captured links. See the full registry on GitHub.</p>`:''}</section>
      <div class="status-disclaimer">${icon('shield',15)} Status data is a historical snapshot generated by the scheduled workflow, not a live website probe. GitHub Pages is public and read-only; editorial approvals happen in the source repository. <a href="https://github.com/vanessa-qiuy/conference-atlas/tree/main/data" target="_blank" rel="noopener noreferrer">Inspect data files ${icon('external',13)}</a></div>
    </main>`;
  }
  function render(){let hash=window.location.hash.replace(/^#\/?/,'').split('?')[0];state.route=['home','explore','calendar','map','status'].includes(hash)?hash:'home';app.innerHTML=nav()+(state.route==='home'?home():state.route==='explore'?explore():state.route==='calendar'?calendar():state.route==='map'?map():dataStatus())+footer()+(state.drawer?detailDrawer(state.drawer):'');document.title=state.route==='home'?'Conference Atlas — Discover. Track. Plan.':`${state.route==='explore'?'Conference Directory':state.route==='calendar'?'Academic Calendar':state.route==='status'?'Data Status':'World Conference Map'} — Conference Atlas`;document.body.style.overflow=state.drawer?'hidden':'';}
  function go(route){state.drawer=null;location.hash='#/'+route;render();scrollTo({top:0,behavior:'instant'});}
  function updateSaved(id){if(state.saved.has(id))state.saved.delete(id);else state.saved.add(id);try{localStorage.setItem('atlas_saved_v1',JSON.stringify([...state.saved]));}catch(e){}render();}
  function escapeICS(x){return String(x||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');}
  function makeICS(items){const toCompact=x=>x.replaceAll('-','');const addDate=x=>{const d=new Date(x+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+1);return d.toISOString().slice(0,10).replaceAll('-','');};const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Conference Atlas//Academic Calendar//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH'];items.forEach(e=>{const desc=`${e.label}. Official source: ${e.source||e.conference.source}`;lines.push('BEGIN:VEVENT',`UID:${e.id}@conference-atlas`, `DTSTAMP:${new Date().toISOString().replaceAll(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART;VALUE=DATE:${toCompact(e.date)}`,`DTEND;VALUE=DATE:${addDate(e.date)}`,`SUMMARY:${escapeICS(e.conference.acronym+' — '+e.label)}`,`DESCRIPTION:${escapeICS(desc)}`,`URL:${safeURL(e.source||e.conference.website)}`,'END:VEVENT');});lines.push('END:VCALENDAR');return lines.join('\r\n')+'\r\n';}
  function downloadCalendar(items,file){const a=document.createElement('a'),blob=new Blob([makeICS(items)],{type:'text/calendar;charset=utf-8'});a.href=URL.createObjectURL(blob);a.download=file;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}
  document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(action==='close-overlay'&&e.target!==el)return;if(el.tagName==='BUTTON')e.preventDefault();
    if(action==='toggle-save')return updateSaved(el.dataset.id);
    if(action==='map-select')return mapSelect(el.dataset.id);
    if(action==='map-zoom-in')return mapZoom(1.5);
    if(action==='map-zoom-out')return mapZoom(1/1.5);
    if(action==='map-world')return mapFocus('World');
    if(action==='map-focus')return mapFocus(el.dataset.focus);
    if(action==='map-clear'){Object.assign(state,{mapField:'All fields',mapYear:'All years',mapRegionFilter:'All regions',mapSearch:'',mapSavedOnly:false,mapZoom:1,mapCenter:{x:600,y:305},mapFocus:'World'});return render();}
    if(action==='detail'){state.drawer=conferences.find(c=>c.id===el.dataset.id);return render();}
    if(action==='close'||action==='close-overlay'){state.drawer=null;return render();}
    if(action==='explore'||action==='calendar'||action==='map'||action==='search')return go(action==='search'?'explore':action);
    if(action==='saved'){state.savedOnly=true;return go('explore');}
    if(action==='field'){state.field=el.dataset.field;state.savedOnly=false;return go('explore');}
    if(action==='view-table'||action==='view-cards'){state.view=action==='view-table'?'table':'cards';return render();}
    if(action==='clear'){Object.assign(state,{search:'',field:'All fields',years:[],regions:[],status:'All statuses',savedOnly:false});return render();}
    if(action==='prev-month'||action==='next-month'){let d=new Date(Date.UTC(state.calYear,state.month+(action==='prev-month'?-1:1),1));state.month=d.getUTCMonth();state.calYear=d.getUTCFullYear();return render();}
    if(action==='today'){const now=new Date();state.calYear=now.getFullYear();state.month=now.getMonth();state.selectedDate=localToday();return render();}
    if(action==='select-day'){state.selectedDate=el.dataset.date;const d=dateParts(state.selectedDate);state.month=d.getUTCMonth();state.calYear=d.getUTCFullYear();return render();}
    if(action==='cal-filter'){state.calType=el.dataset.type;return render();}
    if(action==='download-ics')return downloadCalendar(events,'conference-atlas-all-milestones.ics');
    if(action==='download-single')return downloadCalendar(events.filter(x=>x.conference.id===el.dataset.id),`conference-atlas-${el.dataset.id}.ics`);
  });
  document.addEventListener('change',e=>{
    if(e.target.id==='sort'){state.sort=e.target.value;render();return;}
    if(e.target.dataset.mapFilter){state[e.target.dataset.mapFilter]=e.target.value;state.mapZoom=1;state.mapCenter={x:600,y:305};state.mapFocus='World';return render();}
    if(e.target.id==='mapSavedOnly'){state.mapSavedOnly=e.target.checked;state.mapZoom=1;state.mapCenter={x:600,y:305};state.mapFocus='World';return render();}
    const typ=e.target.dataset.check,val=e.target.value;if(!typ)return;
    if(typ==='field')state.field=val;else if(typ==='year'||typ==='region'){const key=typ==='year'?'years':'regions';state[key]=e.target.checked?[...new Set([...state[key],val])]:state[key].filter(x=>x!==val);}else if(typ==='status')state.status=val;else if(typ==='saved')state.savedOnly=e.target.checked;render();
  });
  document.addEventListener('input',e=>{
    if(e.target.id==='listSearch'){state.search=e.target.value;const start=e.target.selectionStart;render();const next=document.getElementById('listSearch');next?.focus();next?.setSelectionRange(start,start);}
    if(e.target.id==='mapSearch'){state.mapSearch=e.target.value;state.mapZoom=1;state.mapCenter={x:600,y:305};state.mapFocus='World';const start=e.target.selectionStart;render();const next=document.getElementById('mapSearch');next?.focus();next?.setSelectionRange(start,start);}
  });
  document.addEventListener('submit',e=>{if(e.target.id==='heroSearch'){e.preventDefault();state.search=document.getElementById('homeSearch').value;state.field='All fields';go('explore');}});
  let mapDrag=null;
  document.addEventListener('pointerdown',e=>{const svg=e.target.closest?.('#atlasMapSVG');if(!svg||e.target.closest?.('.atlas-marker')||state.mapZoom<=1||e.button!==0)return;const rect=svg.getBoundingClientRect(),v=mapViewBox();mapDrag={id:e.pointerId,atX:e.clientX,atY:e.clientY,center:{...state.mapCenter},ratio:Math.min(rect.width/v.width,rect.height/v.height)};svg.setPointerCapture?.(e.pointerId);});
  document.addEventListener('pointermove',e=>{if(!mapDrag||e.pointerId!==mapDrag.id)return;const deltaX=(e.clientX-mapDrag.atX)/mapDrag.ratio,deltaY=(e.clientY-mapDrag.atY)/mapDrag.ratio;state.mapCenter={x:mapDrag.center.x-deltaX,y:mapDrag.center.y-deltaY};state.mapFocus='';const v=mapViewBox(),svg=document.getElementById('atlasMapSVG');if(svg)svg.setAttribute('viewBox',`${v.x} ${v.y} ${v.width} ${v.height}`);});
  const stopDrag=e=>{if(mapDrag&&e.pointerId===mapDrag.id){mapDrag=null;}};
  document.addEventListener('pointerup',stopDrag);document.addEventListener('pointercancel',stopDrag);
  document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.classList?.contains('atlas-marker')){e.preventDefault();mapSelect(e.target.dataset.id);}if(e.key==='Escape'&&state.drawer){state.drawer=null;render();}});
  window.addEventListener('hashchange',()=>{state.drawer=null;render();window.scrollTo(0,0);});
  render();
})();
